package com.netbanking.account.service; import com.netbanking.account.entity.*; import com.netbanking.account.exception.*; import com.netbanking.account.repository.AccountPinRepository; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.LocalDateTime;
@Service public class PinService {private final AccountService accounts;private final AccountPinRepository pins;private final PasswordEncoder encoder;public PinService(AccountService a,AccountPinRepository p,PasswordEncoder e){accounts=a;pins=p;encoder=e;}@Transactional public void set(Long id,String rawPin){Account a=accounts.account(id);pins.save(pins.findById(id).map(p->{if(!encoder.matches(rawPin,p.getPinHash()))return new AccountPin(a,encoder.encode(rawPin));return p;}).orElseGet(()->new AccountPin(a,encoder.encode(rawPin))));}@Transactional public boolean verify(Long id,String rawPin){AccountPin p=pins.findById(id).orElseThrow(()->new NotFoundException("PIN has not been set"));if(p.getLockedUntil()!=null&&p.getLockedUntil().isAfter(LocalDateTime.now()))throw new ConflictException("PIN is temporarily locked");if(encoder.matches(rawPin,p.getPinHash())){p.reset();return true;}p.failed();return false;}}
